# 全局“换乘表”：记录 (当前所在挂载, 踩到的目录节点) -> 要切换过去的新挂载
mount_table = {
    (ext4_mount, dentry_tmp): tmpfs_mount
}

# 内存里的“查表笔记”缓存：记录 (父目录节点, 名字) -> 子目录节点
dentry_cache = {}

<p></p>

def resolve_path(path_str):
    # 1. 确定起点：以 '/' 开头的路径，直接站在系统根挂载的根目录上
    cur_mount  = root_mount               # ext4_mount
    cur_dentry = root_mount.root_dentry   # ext4 的 '/'

    # 2. 把 "/tmp/a.txt" 切分成 ["tmp", "a.txt"]，一段一段往前走
    for name in split_path(path_str):

        # -------- 第一步：查表找下一级节点 --------
        # 先翻内存里的笔记，记过就直接拿，省去读磁盘
        next_dentry = dentry_cache.get((cur_dentry, name))

        if next_dentry is None:
            # 内存没命中，调用“当前挂载对应的文件系统驱动”去底层查表
            # (第1轮调用的是 ext4 驱动，第2轮会自动变成调用 tmpfs 驱动)
            inode = cur_mount.fs.lookup(cur_dentry.inode, name)
            if inode is None:
                return Error("文件不存在 ENOENT")

            # 查到了，顺手建一张内存笔记并缓存起来
            next_dentry = Dentry(name=name, parent=cur_dentry, inode=inode)
            dentry_cache[(cur_dentry, name)] = next_dentry

        # 往前迈一步
        cur_dentry = next_dentry

        # -------- 第二步：检查是否触发“换乘” --------
        # 用 while 是为了兼容“同一个目录上连续叠挂了多个文件系统”的情况
        while (cur_mount, cur_dentry) in mount_table:
            next_mount = mount_table[(cur_mount, cur_dentry)]
            cur_mount  = next_mount
            cur_dentry = next_mount.root_dentry  # 原地切到新文件系统的根目录

    # 走完所有片段，返回最终落脚点（二元组坐标）
    return (cur_mount, cur_dentry)

<p></p>

def sys_open(path_str, mode):
    # 1. 路径解析，拿到目标位置
    (mount, dentry) = resolve_path(path_str)

    # 2. 权限检查：先看“挂载规则”，再看“文件自身权限”
    if mode == WRITE and mount.read_only:
        return Error("只读挂载，禁止写入 EROFS")
    if not check_inode_permission(dentry.inode, mode):
        return Error("权限不足 EACCES")

    # 3. 在内存中生成“打开的文件实例”，放进当前进程的 fd 表
    file_obj = OpenFile(mount=mount, dentry=dentry, inode=dentry.inode, offset=0)
    fd = current_process.fd_table.alloc(file_obj)
    return fd

$$
\text{进程里的编号（\texttt{fd}）} \longrightarrow \text{一次打开产生的会话（Open File）} \longrightarrow \text{文件本体（Inode）}
$$
